import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·29","description":"易小帖 - 卷五·29","frontmatter":{"title":"卷五·29","description":"易小帖 - 卷五·29"},"headers":[],"relativePath":"classics/yixiaotie/151.md","filePath":"classics/yixiaotie/151.md"}'),o={name:"classics/yixiaotie/151.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·29",tabindex:"-1"},[r("卷五·29 "),e("a",{class:"header-anchor",href:"#卷五·29","aria-label":"Permalink to “卷五·29”"},"​")],-1),e("p",null,"又曰：參天兩地而倚數，以上文讀之，謂蓍依之以立，數也。筮法老陽數九，九乾天也。老陰數六，六坤地也。三奇為老陽，三三奇而九，是參天也。三偶為老陰，兩三偶而六是兩地也。言周易之佔，九六也。佔法用九六七八者，先生河洛原舛，編解五位相得而各有合曰：衍數以五為主，一合五為六，二合五為七，三合五為八，四合五為九，故用九六七八也。不用十者，再五為十，即五也。且衍法有一（除一不用）二（分而為二）三（掛一象三）四（揲之以四）而成卦用，九六七八總為大衍之數五十，而天地之數備矣。若老變而少不變，以陽九為老，陰六為老者，蓋以陽主上進，九六七八則九無可進，故曰老陽。昔人雲：退變而為八，陰主下。退九六七八，則六無可退，故曰老陰。昔人曰：進變而為七。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
